<template>
  <section v-if="mounted" v-show="open" class="pdf-reading-note-task" role="region" aria-label="PDF 阅读笔记任务" :inert="mobileHelpOpen||undefined" @keydown.esc.stop.prevent="back">
    <div class="reading-note-surface" :inert="actions||undefined" :aria-hidden="actions||undefined">
      <header class="reading-note-header"><button class="reading-note-icon" :aria-label="phase==='select'?'返回批注列表':phase==='source'?'返回阅读笔记':'返回选择'" :disabled="busy" @click="back"><ArrowLeft :size="22" aria-hidden="true" /></button><h1 ref="heading" tabindex="-1"><span v-for="part in titleParts" :key="part">{{ part }}</span></h1><button v-if="phase==='select'" class="reading-note-icon" aria-label="筛选摘录" :class="{'is-active':filterActive}" @click="openFilters"><Filter :size="22" aria-hidden="true" /></button><MobileHelp v-if="phase!=='select'" :topic="phase==='preview'||phase==='source'?'readingNotePreview':phase==='saved'?'readingNoteSaved':'readingSelection'" /><button v-if="phase!=='filters'&&phase!=='source'" ref="more" class="reading-note-icon" :aria-label="phase==='select'?'摘录选择操作':'阅读笔记操作'" aria-haspopup="dialog" :aria-expanded="actions" :disabled="busy" @click="openActions"><EllipsisVertical :size="22" aria-hidden="true" /></button></header>
      <div class="reading-note-context assistive-status"><p>{{ name }}</p><span>{{ phase==='preview'||phase==='saved'?`${preview?.document.annotations.length||0} 条 · 独立笔记`:`当前第 ${page} 页` }}</span></div>
      <div ref="body" class="reading-note-body" tabindex="0" role="region" :aria-label="title+'内容'" @focusin="rememberFocus">
        <p v-if="!actions&&(localError||error)" class="reading-note-error" role="alert">{{ localError||error }}</p>
        <template v-if="phase==='select'">
          <button v-if="draft" class="reading-note-resume" data-reading-focus="resume" @click="emit('resume',$event.currentTarget as HTMLElement)"><span><strong>继续这次输入</strong><small>第 {{ draft.page }} 页 · {{ kind(draft) }}</small></span><ChevronRight :size="20" aria-hidden="true" /></button>
          <p v-if="message" role="status">{{ message }}</p><p v-if="!canCopy" role="status">这份 PDF 限制复制和摘录，已选内容继续保留。</p>
          <div v-show="queryOpen" class="reading-note-search"><button class="reading-note-icon" aria-label="关闭摘录查找" @click="closeQuery"><ArrowLeft :size="22" aria-hidden="true" /></button><div class="reading-note-query"><Search :size="20" aria-hidden="true" /><input id="pdf-reading-note-query" ref="queryInput" v-model="query" type="search" maxlength="200" aria-label="查找摘录或想法" placeholder="查找摘录或想法" @input="query=($event.target as HTMLInputElement).value" /><button v-if="query" class="reading-note-query-clear" aria-label="清空摘录搜索" @click="clearQuery"><X :size="18" aria-hidden="true" /></button></div></div>
          <button v-if="query&&!queryOpen" class="reading-note-query-chip" @click="openQuery">查找：{{ query }}<Search :size="18" aria-hidden="true" /></button>
          <p class="reading-note-count" role="status"><strong>已选 {{ selectedIds.length }} 条 · 找到 {{ filtered.length }} 条</strong><span v-if="hiddenSelection">其中 {{ hiddenSelection }} 条不在当前范围</span></p>
          <ol v-if="visible.length" class="reading-note-cards"><li v-for="a in visible" :key="a.id" class="reading-note-card" :class="{'is-selected':selectedIds.includes(a.id)}"><label class="reading-note-choice"><span><span class="reading-note-meta"><i class="reading-note-swatch" :class="'color-'+a.color" aria-hidden="true" /><span>第 {{ a.page }} 页 · {{ kind(a) }}</span></span><span class="reading-note-excerpt"><MobilePdfExcerpt v-if="canCopy&&a.quote" :text="a.quote" :color="a.color" :limit="180" /><span v-else>{{ snippet(a.comment||'区域标记') }}</span></span><span class="reading-note-secondary"><MessageSquare :size="18" aria-hidden="true" />{{ a.comment?'有评论':'无评论' }}</span></span><input type="checkbox" :data-reading-focus="a.id" :checked="selectedIds.includes(a.id)" :disabled="busy||!ready||!canCopy" @change="toggle(a.id)" /></label></li></ol>
          <div v-else-if="!loading&&ready" class="reading-note-empty"><MessageSquare v-if="!annotations.length" :size="38" aria-hidden="true" /><Search v-else :size="38" aria-hidden="true" /><h2>{{ annotations.length?'没有匹配的摘录':'还没有批注' }}</h2><button v-if="annotations.length" class="button" @click="clearFilters">清空搜索与筛选</button></div>
          <p v-if="loading" role="status">正在读取批注…</p><button v-if="!loading&&!ready" class="button" :disabled="busy||!!draft" @click="emit('reload')">重新读取批注</button><button v-if="visibleCount<filtered.length" class="button" @click="visibleCount+=50">再显示 50 条摘录</button>
        </template>
        <div v-else-if="phase==='filters'" class="reading-note-filters"><fieldset><legend>标记颜色</legend><div class="reading-note-colors"><label v-for="(label,c) in allColors" :key="c" class="reading-note-color"><i v-if="c!=='all'" class="reading-note-swatch" :class="'color-'+c" aria-hidden="true" /><span>{{ label }}</span><input v-model="prepared.color" type="radio" name="pdf-reading-note-color" :value="c" :data-reading-focus="'color-'+c" /></label></div></fieldset><label class="reading-note-switch"><span>仅当前页<small>第 {{ page }} 页</small></span><input v-model="prepared.page" type="checkbox" data-reading-focus="page" /></label><label v-if="selectedIds.length||prepared.selected" class="reading-note-switch"><span>仅看已选摘录<small>已选 {{ selectedIds.length }} 条</small></span><input v-model="prepared.selected" type="checkbox" data-reading-focus="selected" /></label><button class="button reading-note-reset" @click="resetPrepared">重置筛选</button></div>
        <article v-else-if="phase==='preview'&&preview" class="reading-note-preview"><p class="reading-note-preview-label">预览（Markdown）</p><h2>阅读笔记</h2><p class="reading-note-preview-source">来源：{{ name }}</p><section v-if="previewQuotes.length" class="reading-note-preview-group"><h3>关键摘录</h3><div v-for="a in previewQuotes" :key="a.id" class="reading-note-preview-excerpt" :class="'note-color-'+a.color"><blockquote>{{ a.quote }}</blockquote><button class="reading-note-reference" :data-reading-focus="a.id+'-reference'" :disabled="busy||!ready" @click="reference(a)"><Link2 :size="20" aria-hidden="true" /><span>原文第 {{ a.page }} 页</span></button></div></section><section v-if="previewComments.length" class="reading-note-preview-group"><h3>我的批注</h3><ul><li v-for="a in previewComments" :key="a.id"><p>{{ a.comment }}</p><button v-if="!a.quote" class="reading-note-reference" :data-reading-focus="a.id+'-reference'" :disabled="busy||!ready" @click="reference(a)"><Link2 :size="20" aria-hidden="true" /><span>原文第 {{ a.page }} 页</span></button></li></ul></section><button v-if="preview.document.annotations.some(a=>!a.quote&&!a.comment)" class="reading-note-reference" :disabled="busy||!ready" @click="showSource">查看区域标记来源</button></article>
        <article v-else-if="phase==='source'&&preview" class="reading-note-source"><pre>{{ preview.content }}</pre></article>
        <div v-else-if="phase==='saved'&&note" class="reading-note-success"><CircleCheck :size="44" aria-hidden="true" /><h2>阅读笔记已保存</h2><div class="reading-note-success-card"><strong>{{ noteTitle }} · 阅读笔记</strong><span>Markdown · 手机资料库</span></div><details><summary>文件名称</summary><p>{{ note.relativePath }}</p></details><button class="reading-note-continue" @click="back">继续选择</button></div>
      </div>
      <footer v-if="phase!=='source'" class="reading-note-footer"><template v-if="phase==='select'"><button class="button primary-button" :disabled="busy||loading||!!draft||!ready||!canCopy||!selectedIds.length" @click="prepareReview">预览笔记 · {{ selectedIds.length }} 条</button></template><template v-else-if="phase==='filters'"><button class="button primary-button" :disabled="busy" @click="applyFilters">应用筛选</button></template><template v-else-if="phase==='preview'"><button class="button primary-button" :disabled="busy||!canCopy||!ready" @click="saveReview">{{ busy?'正在保存…':'存为笔记' }}</button></template><template v-else><button class="button primary-button" :disabled="!note" @click="emit('open-note')">打开阅读笔记</button></template></footer>
    </div>
    <div v-if="actions" class="reading-note-layer" @click.self="closeActions"><section ref="dialog" class="reading-note-dialog" role="dialog" aria-modal="true" :aria-label="phase==='select'?'选择操作':'笔记操作'" @keydown.tab.prevent="dialogTab" @keydown.esc.stop.prevent="closeActions"><header><h2 ref="dialogHeading" tabindex="-1">{{ phase==='select'?'选择操作':'笔记操作' }}</h2><button class="reading-note-icon" :aria-label="phase==='select'?'返回摘录选择':'返回阅读笔记'" @click="closeActions"><X :size="22" aria-hidden="true" /></button></header><div class="reading-note-dialog-body" tabindex="0" role="region" aria-label="选择操作内容"><template v-if="phase==='select'"><button class="reading-note-action" @click="openQuery"><Search :size="20" aria-hidden="true" /><span>查找摘录</span></button><button class="reading-note-action" :disabled="busy" @click="openFilters"><ListFilter :size="20" aria-hidden="true" /><span>筛选摘录</span></button><button class="reading-note-action" :disabled="!ready||!canCopy||busy||!filtered.length" @click="selectMatches"><CheckSquare :size="20" aria-hidden="true" /><span>选择当前结果 · {{ filtered.length }} 条</span></button><button class="reading-note-action" :disabled="!selectedIds.length&&!onlySelected" :aria-pressed="onlySelected" @click="toggleOnlySelected"><ListFilter :size="20" aria-hidden="true" /><span>{{ onlySelected?'显示全部范围':'仅看已选' }}</span></button><button class="reading-note-action" :disabled="!selectedIds.length||busy" @click="clearSelection"><Trash2 :size="20" aria-hidden="true" /><span>清空已选</span></button><button class="reading-note-action" :disabled="busy||loading||!!draft" @click="reload"><RefreshCw :size="20" aria-hidden="true" /><span>重新读取批注</span></button><div class="reading-note-help-row"><span>选择说明</span><MobileHelp topic="readingSelection" /></div></template><template v-else><button class="reading-note-action" data-reading-action="source" @click="showSource"><FileCode2 :size="20" aria-hidden="true" /><span>查看笔记源码</span></button><button class="reading-note-action" @click="returnSelection"><ListFilter :size="20" aria-hidden="true" /><span>返回选择</span></button></template><p v-if="localError" class="reading-note-error" role="alert">{{ localError }}</p></div></section></div>
  </section>
</template>
<script setup lang="ts">
import {computed,nextTick,ref,watch} from 'vue'
import {ArrowLeft,EllipsisVertical,Filter,FileCode2,Link2,X,Search,ListFilter,MessageSquare,CheckSquare,Trash2,RefreshCw,ChevronRight,CircleCheck} from 'lucide-vue-next'
import MobileHelp from './MobileHelp.vue'
import MobilePdfExcerpt from './MobilePdfExcerpt.vue'
import {mobileHelpOpen} from './mobileHelp'
import {canFocus,focusableControls} from './accessibility'
import {filterAnnotations,addReadingSelection} from './pdfCuration'
import type {PdfAnnotation,PdfAnnotationDocument} from '../types/pdfAnnotations'
import type {Identity} from './storage'
type Phase='select'|'filters'|'preview'|'source'|'saved'
type Color=PdfAnnotation['color']|'all'
type Prepared={color:Color;page:boolean;selected:boolean}
const props=defineProps<{open:boolean;name:string;page:number;annotations:PdfAnnotation[];selectedIds:string[];canCopy:boolean;ready:boolean;loading:boolean;busy:boolean;error:string;message:string;draft?:PdfAnnotation;preview:{document:PdfAnnotationDocument;target:Identity;content:string}|null;note:Identity|null;initialQuery:string;initialColor:Color;initialPage:boolean;initialSelected:boolean;prepare:()=>Promise<boolean>;saveNote:()=>Promise<boolean>}>()
const emit=defineEmits<{'update:selectedIds':[ids:string[]];back:[];reload:[];resume:[target:HTMLElement];reference:[annotation:PdfAnnotation];'open-note':[];clearError:[]}>()
const mounted=ref(false),phase=ref<Phase>('select'),actions=ref(false),heading=ref<HTMLElement>(),body=ref<HTMLElement>(),more=ref<HTMLButtonElement>(),dialog=ref<HTMLElement>(),dialogHeading=ref<HTMLElement>(),queryInput=ref<HTMLInputElement>(),query=ref(''),queryOpen=ref(false),color=ref<Color>('all'),onlyPage=ref(false),onlySelected=ref(false),visibleCount=ref(50),localError=ref(''),prepared=ref<Prepared>({color:'all',page:false,selected:false})
let sourceReturn:{phase:Phase;menu:boolean}|undefined
let initialized=false,filterPrepared=false,querySelection:{start:number|null;end:number|null;direction:'forward'|'backward'|'none'|null}|undefined
const places=new Map<Phase,{scroll:number;target?:HTMLElement;key?:string;id?:string}>(),lastFocus=new Map<Phase,HTMLElement>()
const colors={yellow:'黄色',green:'绿色',pink:'粉色',blue:'蓝色'},allColors={all:'全部颜色',...colors},title=computed(()=>phase.value==='select'?'选择摘录':phase.value==='filters'?'筛选摘录':phase.value==='preview'?'阅读笔记':phase.value==='source'?'笔记源码':'已保存'),noteTitle=computed(()=>props.name.replace(/\.pdf$/i,''))
const filtered=computed(()=>{const source=props.canCopy?props.annotations:props.annotations.map(a=>({...a,quote:''}));const a=filterAnnotations(source,{query:query.value,color:color.value,currentPage:onlyPage.value?props.page:null});return onlySelected.value?a.filter(a=>props.selectedIds.includes(a.id)):a}),visible=computed(()=>filtered.value.slice(0,visibleCount.value)),hiddenSelection=computed(()=>props.selectedIds.filter(id=>!filtered.value.some(a=>a.id===id)).length),filterActive=computed(()=>color.value!=='all'||onlyPage.value||onlySelected.value||!!query.value.trim())
const titleParts=computed(()=>phase.value==='select'?['选择','摘录']:phase.value==='filters'?['筛选','摘录']:phase.value==='preview'?['阅读','笔记']:phase.value==='source'?['笔记','源码']:['已保存'])
const previewQuotes=computed(()=>props.canCopy?(props.preview?.document.annotations||[]).filter(a=>a.quote.trim()):[]),previewComments=computed(()=>(props.preview?.document.annotations||[]).filter(a=>a.comment.trim()))
const kind=(a:{kind:PdfAnnotation['kind']})=>a.kind==='highlight'?'高亮':a.kind==='area'?'区域批注':'评论'
const snippet=(s:string,max=48)=>{const chars=Array.from(s.replace(/\s+/g,' ').trim());return chars.slice(0,max).join('')+(chars.length>max?'…':'')}
function rememberFocus(e:FocusEvent){if(e.target instanceof HTMLElement)lastFocus.set(phase.value,e.target)}
function capture(){if(phase.value==='select'&&queryInput.value){query.value=queryInput.value.value;querySelection={start:queryInput.value.selectionStart,end:queryInput.value.selectionEnd,direction:queryInput.value.selectionDirection}}const active=document.activeElement,target=active instanceof HTMLElement&&body.value?.contains(active)?active:lastFocus.get(phase.value);places.set(phase.value,{scroll:body.value?.scrollTop||0,target,key:target?.dataset.readingFocus,id:target?.id})}
async function restore(){await nextTick();if(!props.open)return;const p=places.get(phase.value);if(body.value)body.value.scrollTop=p?.scroll||0;if(phase.value==='select'&&queryInput.value&&querySelection?.start!=null)queryInput.value.setSelectionRange(querySelection.start,querySelection.end,querySelection.direction||undefined);const target=canFocus(p?.target)?p.target:p?.key?[...(body.value?.querySelectorAll<HTMLElement>('[data-reading-focus]')||[])].find(e=>e.dataset.readingFocus===p.key):p?.id?body.value?.querySelector<HTMLElement>('#'+p.id):heading.value;(canFocus(target)?target:heading.value)?.focus({preventScroll:true})}
watch(()=>props.open,async value=>{if(!value){capture();return}if(!initialized){query.value=props.initialQuery;color.value=props.initialColor;onlyPage.value=props.initialPage;onlySelected.value=props.initialSelected;initialized=true}mounted.value=true;await restore()},{immediate:true})
watch(()=>props.error,async error=>{if(!error||!props.open||actions.value)return;await nextTick();const e=body.value?.querySelector('.reading-note-error');if(e&&body.value){const r=e.getBoundingClientRect(),b=body.value.getBoundingClientRect();body.value.scrollTop+=r.top<b.top?r.top-b.top-8:r.bottom>b.bottom?r.bottom-b.bottom+8:0}})
watch(()=>props.loading,(value,previous)=>{if(previous&&!value&&props.open)void restore()})
watch([query,color,onlyPage,onlySelected,()=>props.page],()=>visibleCount.value=50)
function toggle(id:string){if(props.busy||!props.ready||!props.canCopy)return;try{const next=props.selectedIds.includes(id)?props.selectedIds.filter(v=>v!==id):addReadingSelection(props.selectedIds,[id]);localError.value='';emit('update:selectedIds',next)}catch(e){localError.value=String((e as Error).message)}finally{void nextTick(()=>{const input=[...(body.value?.querySelectorAll<HTMLInputElement>('input[data-reading-focus]')||[])].find(e=>e.dataset.readingFocus===id);if(input)input.checked=props.selectedIds.includes(id)})}}
async function openActions(){capture();actions.value=true;await nextTick();dialogHeading.value?.focus({preventScroll:true})}
async function closeActions(){actions.value=false;await nextTick();more.value?.focus({preventScroll:true})}
function selectMatches(){try{const next=addReadingSelection(props.selectedIds,filtered.value.map(a=>a.id));localError.value='';emit('update:selectedIds',next);void closeActions()}catch(e){localError.value=(e as Error).message}}
function clearSelection(){emit('update:selectedIds',[]);localError.value='';void closeActions()}
function toggleOnlySelected(){onlySelected.value=!onlySelected.value;filterPrepared=false;places.delete('select');void closeActions()}
async function reload(){capture();await closeActions();emit('reload')}
function dialogTab(e:KeyboardEvent){const controls=focusableControls(dialog.value),i=controls.indexOf(document.activeElement as HTMLElement);if(controls.length)controls[(i+(e.shiftKey?-1:1)+controls.length)%controls.length]?.focus()}
function openFilters(){capture();actions.value=false;if(!filterPrepared){prepared.value={color:color.value,page:onlyPage.value,selected:onlySelected.value};filterPrepared=true}phase.value='filters';void restore()}
function resetPrepared(){prepared.value={color:'all',page:false,selected:false}}
function applyFilters(){const changed=color.value!==prepared.value.color||onlyPage.value!==prepared.value.page||onlySelected.value!==prepared.value.selected;capture();color.value=prepared.value.color;onlyPage.value=prepared.value.page;onlySelected.value=prepared.value.selected;if(changed)places.delete('select');phase.value='select';void restore()}
function clearFilters(){query.value='';color.value='all';onlyPage.value=false;onlySelected.value=false;filterPrepared=false;void openQuery()}
function clearQuery(){query.value='';queryInput.value?.focus({preventScroll:true})}
async function openQuery(){if(actions.value)await closeActions();queryOpen.value=true;await nextTick();queryInput.value?.focus({preventScroll:true})}
function closeQuery(){capture();queryOpen.value=false;void nextTick(()=>heading.value?.focus({preventScroll:true}))}
function reference(annotation:PdfAnnotation){if(props.busy||!props.ready)return;capture();emit('reference',annotation)}
function showSource(){capture();sourceReturn={phase:phase.value,menu:actions.value};actions.value=false;phase.value='source';void restore()}
async function returnFromSource(){phase.value=sourceReturn?.phase||'preview';await restore();if(sourceReturn?.menu){actions.value=true;await nextTick();dialog.value?.querySelector<HTMLElement>('[data-reading-action=source]')?.focus({preventScroll:true})}}
function returnSelection(){actions.value=false;phase.value='select';void restore()}
async function prepareReview(){if(props.busy||props.draft||!props.canCopy||!props.ready)return;capture();localError.value='';const previous=props.preview;if(await props.prepare()){if(previous?.target.relativePath!==props.preview?.target.relativePath||previous?.content!==props.preview?.content)places.delete('preview');phase.value='preview';void restore()}}
async function saveReview(){if(props.busy)return;capture();if(await props.saveNote()){phase.value='saved';places.delete('saved');void restore()}}
function back(){if(!props.open)return false;if(props.busy)return true;if(actions.value){void closeActions();return true}capture();if(phase.value==='source'){void returnFromSource();return true}if(phase.value!=='select'){if(phase.value==='preview')emit('clearError');phase.value='select';void restore()}else if(queryOpen.value)closeQuery();else emit('back');return true}
defineExpose({back,capture,restore})
</script>
<style scoped>
.pdf-reading-note-task{--note-error:#a13e32;position:absolute;inset:0;z-index:18;display:flex;flex-direction:column;min-height:0;overflow:hidden;background:var(--bg);color:var(--ink)}
.reading-note-surface{display:flex;flex:1;flex-direction:column;min-height:0}.reading-note-header{display:flex;align-items:center;gap:8px;min-height:64px;padding:7.5px 8px;border-bottom:1px solid var(--line);flex:none}.reading-note-header h1{flex:1;min-width:0;margin:0;font-size:1.25rem;line-height:1.5;letter-spacing:normal;font-weight:700;overflow-wrap:anywhere}.reading-note-header h1 span{display:inline-block;white-space:nowrap}.reading-note-icon{display:grid;place-items:center;flex:0 0 48px;width:48px;height:48px;min-width:48px;min-height:48px;padding:0;border:0;background:transparent;color:var(--ink)}.reading-note-icon.is-active{border-radius:10px;color:var(--primary);background:var(--primary-soft)}
.reading-note-body{flex:1;min-height:0;padding:16px;overflow:auto;overscroll-behavior:contain}.reading-note-search{display:flex;align-items:center;gap:8px}.reading-note-query{flex:1;position:relative;min-width:0}.reading-note-query>svg{position:absolute;left:12px;top:50%;transform:translateY(-50%);color:var(--muted);pointer-events:none}.reading-note-query input{display:block;width:100%;min-width:0;min-height:48px;padding:10px 48px 10px 40px;font:inherit;font-size:1rem;line-height:1.5;color:var(--ink);background:var(--surface);border:1px solid var(--line);border-radius:10px;appearance:none}.reading-note-query input::-webkit-search-cancel-button{display:none}.reading-note-query input::placeholder{color:var(--muted);opacity:1}.reading-note-query-clear{position:absolute;right:0;top:0;display:grid;place-items:center;width:48px;min-height:48px;height:100%;padding:0;border:0;background:transparent;color:var(--muted)}
.reading-note-query-chip{display:flex;align-items:center;gap:8px;justify-content:space-between;width:100%;min-height:48px;padding:8px 12px;border:1px solid var(--line);border-radius:10px;background:var(--primary-soft);color:var(--primary);font:inherit;font-size:.875rem;line-height:1.5;text-align:left;overflow-wrap:anywhere}.reading-note-query-chip svg{flex:none}
